DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    -- Delete existing CAM 21 if any
    DELETE FROM public.topics WHERE name = 'CAM 21' AND user_id IS NULL;
    
    -- Insert CAM 21 topic
    VALUES (gen_random_uuid(), NULL, 'CAM 21', 'school', 'CAM', NOW() + interval '11 seconds')
    RETURNING id INTO v_topic_id;
    
END $$;